        print(f\"R&D T{tier['tier']} in progress\")
    elif tier.get('completed_count', 0) > 0:
        print(f\"R&D T{tier['tier']}: completed {tier['completed_count']}, total boost {tier.get('total_boost', 0):.4f}\")
    else:
