import novamind_api as nm

# Check cost info for capacity tiers
try:
    cost_info = nm.infrastructure.get_cost_info()
    print('=== Cost Info ===')
    print(cost_info)
except Exception as e:
    print(f'Error: {e}')

# Check social posts
try:
    posts = nm.analytics.get_social_posts(days=7, limit=20)
    print('\n=== Social Posts (7 days) ===')
    if isinstance(posts, list):
        for p in posts[:20]:
            print(p)
    else:
        print(posts)
except Exception as e:
    print(f'Posts Error: {e}')

# Check market overview
try:
    overview = nm.market.get_market_overview()
    print('\n=== Market Overview ===')
    print(overview)
except Exception as e:
    print(f'Overview Error: {e}')
"

