import novamind_api as nm

# Check ledger for this week
r = nm.query('''SELECT entry_type, category, ROUND(amount, 2) as amt, day 
FROM ledger WHERE day >= 245 AND day <= 252 ORDER BY day DESC, entry_type LIMIT 40''')
print('Ledger entries (day 245-252):')
for row in r['rows']:
    print(f'  Day {row[\"day\"]}: {row[\"entry_type\"]} {row[\"category\"]} \${row[\"amt\"]}')

# Check social posts
r2 = nm.analytics.get_social_posts(days=7, limit=20)
print('\nRecent social posts:')
if isinstance(r2, list):
    for p in r2[:15]:
        if isinstance(p, dict):
            print(f'  {p}')
        else:
            print(f'  {p}')
else:
    print(r2)
"

