import novamind_api as nm

# Get social posts
r = nm.analytics.get_social_posts(days=14, limit=50)
print(type(r))
if isinstance(r, dict):
    for k,v in r.items():
        print(f'{k}: {type(v)}')
        if isinstance(v, list):
            for item in v[:10]:
                print(item)
        else:
            print(v)
elif isinstance(r, list):
    for item in r[:10]:
        print(item)
"

