import novamind_api as nm

# Get cost info
cost = nm.infrastructure.get_cost_info()
print('=== Cost Info ===')
if isinstance(cost, list):
    for tier in cost:
        print(tier)
elif isinstance(cost, dict):
    for k, v in cost.items():
        print(f'{k}: {v}')
"

