./novamind-operation python-c "
import novamind_api as nm

# Current quality components
base = 0.20
global_bonus = 0.2346  # from dashboard

# Quality at different tiers per group
groups = {'S1': 0.0047, 'S2': 0.0181, 'S3': 0.0, 'E1': 0.0, 'E2': 0.0, 'E3': 0.0}
tiers = {1: 0.6, 2: 0.75, 3: 0.9, 4: 1.0, 5: 1.1}

print('=== Quality at each tier ===')
for g, bonus in groups.items():
    for t, mult in tiers.items():
        q = (base + global_bonus + bonus) * mult
        print(f'{g} T{t}: {q:.4f}')
    print()

# WTP values (info level 1, +-65% noise)
wtp = {'S1': 25.87, 'S2': 178.59, 'S3': 192.98}
q_min_orig = {'S1': 0.081, 'S2': 0.370, 'S3': 0.145}

print('=== Required quality at different prices ===')
for g in ['S1', 'S2', 'S3']:
    w = wtp[g]
    qm = q_min_orig[g]
    print(f'{g} (WTP={w}, q_min_orig={qm}):')
    for price in [0, 1, 3, 5, 10, 20]:
        if price < w:
            req_q = qm / (1 - price/w)
            print(f'  At \${price}: required_q = {req_q:.4f}')
    print()

print('=== Max q_min that works at each price/tier ===')
for g in ['S1', 'S2']:
    w = wtp[g]
    bonus = groups[g]
    for price in [1, 3, 5]:
        for t in [1, 2, 3, 4, 5]:
            q = (base + global_bonus + bonus) * tiers[t]
            if price < w:
                max_qmin = q * (1 - price/w)
                compute_per_day = 5 * {1:0.0003, 2:0.002, 3:0.006, 4:0.012, 5:0.03}[t]
                monthly_compute = compute_per_day * 30
                margin = price - monthly_compute
                if margin > 0:
                    print(f'{g} \${price} T{t}: max_qmin={max_qmin:.4f}, compute=\${monthly_compute:.2f}/mo, margin=\${margin:.2f}/mo')
    print()
"

